sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    // Add your code here
    if (current.instance.trade_task_reference.case_task_type == 'QTRACK'); {
		//MSSRBXCE-443: Checking if outbound email with same email_id exists
        var glideHSBCEmailLogs = new GlideRecord('x_hsb11_hsbcmss_eh_hsbc_email_log');
		var res = checkOutboundEmailAlreadyExists();

        var emailLog = new GlideRecord('x_hsb11_hsbcmss_eh_hsbc_email_log');
		//MSSRBXCE-241: Populating Trade Case & Task number using first Child record
		var grChildRecords = new GlideRecord('x_hsb11_hsbcmss_eh_aggregated_trade_email_queue');
		grChildRecords.addQuery('parent',current.instance.sys_id);
		grChildRecords.orderBy('number');
		grChildRecords.query();
		if(grChildRecords.next()){
			emailLog.trade_case_number = grChildRecords.trade_case;
			emailLog.trade_case_task_number = grChildRecords.trade_case_task;
		}
        emailLog.email_log = current.instance.sys_id; //MSSRBXCE-444:Populating parent aggregated record
        emailLog.type = 'Outbound';
        emailLog.api_response_from_qtrack = 'Draft';
        emailLog.importance = current.importance;
        emailLog.user_id = current.user_id;
        emailLog.from = current.user;
        emailLog.to = current.to;
        emailLog.mailbox = current.mailbox;
        emailLog.uid = current.uid;
        emailLog.checkpoint = current.checkpoint;
        emailLog.user = current.user;
        emailLog.deleted = current.deleted;
        emailLog.recipients = current.recipients;
        emailLog.subject = current.subject;
        emailLog.message_id = current.message_id;
        emailLog.haders = current.headers;
        emailLog.error_string = current.error_string;
        emailLog.body = current.body;
        emailLog.email_preview = current.body;
        emailLog.receive_type = current.receive_type;
        emailLog.copied = current.copied;
        emailLog.reply_to = current.reply_to;
        emailLog.body_text = current.body_text;
        emailLog.blind_copied = current.blind_copied;
        emailLog.content_type = current.content_type;
        emailLog.widget = 'QTRACK';
        emailLog.attachment = current.attachment;
        var sys = emailLog.insert();
        //to set type as ignored in sys_email table
        current.type = 'send-ignored';
        current.setWorkflow(false);
        current.update();
        current.setWorkflow(true);

        var emailSubject = new GlideRecord('x_hsb11_hsbcmss_eh_hsbc_email_log');
        emailSubject.get(sys);
        var subject = emailSubject.subject;
		if(!res){
			emailSubject.subject = emailLog.email_id + " " + subject;
		}
		else{
			//MSSRBXCE-443: Adding "Reminder" for reminder email
			emailSubject.subject = "Reminder " + glideHSBCEmailLogs.email_id + " " + subject;
			//MSSRBXCE-91:Populating email_query_id for reminder email
			emailSubject.email_query_id = glideHSBCEmailLogs.email_query_id;
		}

        var emailSNEnumber = emailLog.email_id;
        var emailBody = emailSubject.body.toString();
        emailSubject.body = emailBody.replaceAll('SNE_PLACEHOLDER', emailSNEnumber);
        emailSubject.email_preview = emailBody.replaceAll('SNE_PLACEHOLDER', emailSNEnumber);
        emailSubject.update();
    }

	function checkOutboundEmailAlreadyExists() {
            //MSSRBXCE-443: Function to check if first outbound email already exists
            glideHSBCEmailLogs.addQuery('email_log', current.instance.sys_id);
            glideHSBCEmailLogs.addQuery('type', 'Outbound');
            glideHSBCEmailLogs.query();
            if (glideHSBCEmailLogs.next())
                return true;
            else
                return false;
    }

})(current, previous);
